package com.smartblog.service.impl;
import com.smartblog.dto.request.*; import com.smartblog.dto.response.LoginResponse; import com.smartblog.entity.*; import com.smartblog.exception.BusinessException; import com.smartblog.mapper.*; import com.smartblog.service.*; import com.smartblog.util.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.time.LocalDateTime;
@Service public class AuthServiceImpl implements AuthService { private final UserMapper userMapper; private final UserIdentityMapper identityMapper; private final UserCredentialMapper credentialMapper; private final PasswordEncoder encoder; private final EmailCodeService codeService; private final SecurityEventService eventService; private final SessionService sessionService; @Value("${security.login.max-failures:5}") private Integer maxFailures; @Value("${security.login.failure-window-minutes:15}") private Integer failWindow; public AuthServiceImpl(UserMapper u,UserIdentityMapper i,UserCredentialMapper c,PasswordEncoder e,EmailCodeService code,SecurityEventService ev,SessionService s){userMapper=u;identityMapper=i;credentialMapper=c;encoder=e;codeService=code;eventService=ev;sessionService=s;} @Transactional public void register(RegisterRequest r,HttpServletRequest req){String username=r.username().trim(); String nu=NormalizeUtil.normalizeUsername(username); String email=r.email().trim(); String ne=NormalizeUtil.normalizeEmail(email); if(identityMapper.selectByTypeAndValue(AuthConstants.IDENTITY_USERNAME,nu)!=null) throw new BusinessException("用户名已存在"); if(identityMapper.selectByTypeAndValue(AuthConstants.IDENTITY_EMAIL,ne)!=null) throw new BusinessException("邮箱已被注册"); codeService.verifyCode(AuthConstants.SCENE_REGISTER_EMAIL,ne,r.emailCode()); User user=new User(); user.setNickname(StringUtils.hasText(r.nickname())?r.nickname().trim():username); user.setStatus(AuthConstants.USER_ACTIVE); userMapper.insertUser(user); UserIdentity ui=new UserIdentity(); ui.setUserId(user.getId()); ui.setIdentityType(AuthConstants.IDENTITY_USERNAME); ui.setIdentityValue(username); ui.setNormalizedValue(nu); ui.setVerified(1); ui.setPrimaryIdentity(1); identityMapper.insert(ui); UserIdentity ei=new UserIdentity(); ei.setUserId(user.getId()); ei.setIdentityType(AuthConstants.IDENTITY_EMAIL); ei.setIdentityValue(email); ei.setNormalizedValue(ne); ei.setVerified(1); ei.setPrimaryIdentity(0); identityMapper.insert(ei); UserCredential pc=new UserCredential(); pc.setUserId(user.getId()); pc.setCredentialType(AuthConstants.CREDENTIAL_PASSWORD); pc.setSecretHash(encoder.encode(r.password())); pc.setStatus(1); credentialMapper.insert(pc); eventService.log(user.getId(),AuthConstants.EVENT_REGISTER,AuthConstants.RESULT_SUCCESS,req,nu);} public LoginResponse loginByPassword(LoginRequest r,HttpServletRequest req){String account=r.account().trim(); String na=account.contains("@")?NormalizeUtil.normalizeEmail(account):NormalizeUtil.normalizeUsername(account); String ip=RequestUtil.getClientIp(req); int fails=eventService.countRecentLoginFailures(na,ip,LocalDateTime.now().minusMinutes(failWindow)); if(fails>=maxFailures) throw new BusinessException("登录失败次数过多，请稍后再试"); String type=account.contains("@")?AuthConstants.IDENTITY_EMAIL:AuthConstants.IDENTITY_USERNAME; UserIdentity id=identityMapper.selectByTypeAndValue(type,na); if(id==null){eventService.log(null,AuthConstants.EVENT_LOGIN_FAIL,AuthConstants.RESULT_FAIL,req,na); throw new BusinessException("账号或密码错误");} User user=userMapper.selectById(id.getUserId()); if(user==null||user.getStatus()==null||user.getStatus()!=AuthConstants.USER_ACTIVE){eventService.log(id.getUserId(),AuthConstants.EVENT_LOGIN_FAIL,AuthConstants.RESULT_FAIL,req,na); throw new BusinessException("账号或密码错误");} UserCredential c=credentialMapper.selectActivePasswordByUserId(user.getId()); if(c==null||!encoder.matches(r.password(),c.getSecretHash())){eventService.log(user.getId(),AuthConstants.EVENT_LOGIN_FAIL,AuthConstants.RESULT_FAIL,req,na); throw new BusinessException("账号或密码错误");} String username=getUsername(user.getId()); LoginResponse resp=sessionService.createSession(user.getId(),username,r.deviceName(),req); eventService.log(user.getId(),AuthConstants.EVENT_LOGIN_SUCCESS,AuthConstants.RESULT_SUCCESS,req,na); return resp;} public LoginResponse loginByEmailCode(EmailCodeLoginRequest r,HttpServletRequest req){String email=NormalizeUtil.normalizeEmail(r.email()); codeService.verifyCode(AuthConstants.SCENE_LOGIN_EMAIL,email,r.code()); UserIdentity id=identityMapper.selectByTypeAndValue(AuthConstants.IDENTITY_EMAIL,email); if(id==null||id.getVerified()==null||id.getVerified()!=1){eventService.log(null,AuthConstants.EVENT_LOGIN_FAIL,AuthConstants.RESULT_FAIL,req,email); throw new BusinessException("邮箱或验证码错误");} User user=userMapper.selectById(id.getUserId()); if(user==null||user.getStatus()==null||user.getStatus()!=AuthConstants.USER_ACTIVE){eventService.log(id.getUserId(),AuthConstants.EVENT_LOGIN_FAIL,AuthConstants.RESULT_FAIL,req,email); throw new BusinessException("邮箱或验证码错误");} String username=getUsername(user.getId()); LoginResponse resp=sessionService.createSession(user.getId(),username,r.deviceName(),req); eventService.log(user.getId(),AuthConstants.EVENT_LOGIN_SUCCESS,AuthConstants.RESULT_SUCCESS,req,email); return resp;} private String getUsername(Long userId){UserIdentity u=identityMapper.selectByUserIdAndType(userId,AuthConstants.IDENTITY_USERNAME); return u==null?"user-"+userId:u.getIdentityValue();} }
